// RegionalRedirect describes a control-plane response (HTTP 421) reporting
// that the target resource lives in another jurisdiction, naming the home
// core the request should be retried against.
//
// It tolerates two payload shapes so the client works against both old and
// new servers during rollout:
//
//   - documented:  {"error":"foreign_jurisdiction","homeCoreUrl":"…","jurisdiction":"…","message":"…"}
//   - legacy ad-hoc: {"error":"<human message>","home_core_url":"…","jurisdiction":"…"}
//
// Neither shape is RFC-7807, so the fields arrive in ErrorModel.AdditionalProps
// rather than as typed columns; this reads them from there. Once the server
// only emits the documented shape and the spec types the 421 response, this
// hand-rolled extraction can be replaced by the generated model (see
// internal/coreapi/UPSTREAM.md).
type RegionalRedirect struct {
	// HomeCoreURL is the core to retry against, e.g. "https://us.auth.partial.to".
	HomeCoreURL string
	// Jurisdiction is the home jurisdiction id, e.g. "us" (may be empty).
	Jurisdiction string
	// Message is the server's human-readable explanation (may be empty).
	Message string
}

// Summary is a UX-agnostic one-line description of the redirect, suitable for
// any caller. The CLI layer composes a richer message with a concrete
// remediation hint on top of this.
func (r *RegionalRedirect) Summary() string {
	base := r.Message
	if base == "" {
		if r.Jurisdiction != "" {
			base = fmt.Sprintf("target resource is in jurisdiction %q", r.Jurisdiction)
		} else {
			base = "target resource is in another jurisdiction"
		}
	}
	if r.HomeCoreURL != "" {
		return fmt.Sprintf("%s (home core: %s)", base, r.HomeCoreURL)
	}
	return base
