func renderCoreError(err error) error {
	if err == nil {
		return nil
	}
	// A jurisdiction 421 names the home core to retry against. Turn it into a
	// concrete remediation rather than a bare server message: the request is
	// routed by the active login context's core (see auth.ResolveControlPlaneTarget),
	// so the fix is to switch to a context on the home core.
	if r, ok := coreapi.RegionalRedirectFrom(err); ok {
		return errors.New(regionalRedirectMessage(r))
	}
	if msg := coreapi.APIError(err); msg != "" {
		return errors.New(msg)
	}
	return err
}

// regionalRedirectMessage renders a jurisdiction 421 as an actionable error:
// the server's summary plus how to retarget the control plane onto the home
// core.
func regionalRedirectMessage(r *coreapi.RegionalRedirect) string {
	var b strings.Builder
	b.WriteString(r.Summary())
	if r.HomeCoreURL != "" {
		fmt.Fprintf(&b, "\nLog in to that core and retry, e.g.:\n  entire login %s\n  entire auth use <context-on-%s>",
			r.HomeCoreURL, r.HomeCoreURL)
	}
	return b.String()
}

