import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/go-faster/jx"
	"github.com/ogen-go/ogen/ogenerrors"

	"github.com/entireio/cli/cmd/entire/cli/auth"
)

// jurisdictionErr builds an *ErrorModelStatusCode whose body carries the given
// non-RFC-7807 fields in AdditionalProps, mimicking how the generated decoder
// surfaces a 421 jurisdiction redirect.
func jurisdictionErr(fields map[string]string) *ErrorModelStatusCode {
	props := ErrorModelAdditional{}
	for k, v := range fields {
		props[k] = jx.Raw(fmt.Sprintf("%q", v))
	}
	return &ErrorModelStatusCode{StatusCode: 421, Response: ErrorModel{AdditionalProps: props}}
}

func TestRegionalRedirectFrom(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		err      error
		wantOK   bool
		wantHome string
		wantJuri string
		wantMsg  string
	}{
		{
			name: "legacy ad-hoc shape",
			err: jurisdictionErr(map[string]string{
				"error":         `cluster is in jurisdiction "us"; retry against the home core`,
				"home_core_url": "https://us.auth.partial.to",
				"jurisdiction":  "us",
			}),
			wantOK:   true,
			wantHome: "https://us.auth.partial.to",
			wantJuri: "us",
			wantMsg:  `cluster is in jurisdiction "us"; retry against the home core`,
		},
		{
			name: "documented shape",
			err: jurisdictionErr(map[string]string{
				"error":        "foreign_jurisdiction",
				"homeCoreUrl":  "https://us.auth.partial.to",
				"jurisdiction": "us",
				"message":      "cluster is in jurisdiction \"us\"; retry against the home core",
			}),
			wantOK:   true,
			wantHome: "https://us.auth.partial.to",
			wantJuri: "us",
			wantMsg:  "cluster is in jurisdiction \"us\"; retry against the home core",
		},
		{
			name:   "ordinary API error is not a redirect",
			err:    &ErrorModelStatusCode{StatusCode: 409, Response: ErrorModel{Detail: NewOptString("conflict")}},
			wantOK: false,
		},
		{
			name:   "non-API error is not a redirect",
			err:    errors.New("dial tcp: connection refused"),
			wantOK: false,
		},
		{
			name:     "wrapped redirect is unwrapped",
			err:      fmt.Errorf("create mirror: %w", jurisdictionErr(map[string]string{"homeCoreUrl": "https://eu.auth.partial.to"})),
			wantOK:   true,
			wantHome: "https://eu.auth.partial.to",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got, ok := RegionalRedirectFrom(tc.err)
			if ok != tc.wantOK {
				t.Fatalf("RegionalRedirectFrom() ok = %v, want %v", ok, tc.wantOK)
			}
			if !ok {
				return
			}
			if got.HomeCoreURL != tc.wantHome {
				t.Errorf("HomeCoreURL = %q, want %q", got.HomeCoreURL, tc.wantHome)
			}
			if got.Jurisdiction != tc.wantJuri {
				t.Errorf("Jurisdiction = %q, want %q", got.Jurisdiction, tc.wantJuri)
			}
			if got.Message != tc.wantMsg {
				t.Errorf("Message = %q, want %q", got.Message, tc.wantMsg)
			}
		})
	}
}

// TestAPIError_JurisdictionRedirect verifies a 421 redirect no longer degrades
// to the opaque status line — the actionable summary surfaces instead.
func TestAPIError_JurisdictionRedirect(t *testing.T) {
	t.Parallel()
	err := jurisdictionErr(map[string]string{
		"error":         `cluster is in jurisdiction "us"; retry against the home core`,
		"home_core_url": "https://us.auth.partial.to",
		"jurisdiction":  "us",
	})
	got := APIError(err)
	if !strings.Contains(got, "https://us.auth.partial.to") {
		t.Errorf("APIError() = %q, want it to name the home core", got)
	}
	if strings.Contains(got, "failed with status") {
		t.Errorf("APIError() = %q, should not be the opaque status line", got)
	}
}

