// jurisdictionErr builds an *ErrorModelStatusCode whose body carries the given
// non-RFC-7807 fields in AdditionalProps, mimicking how the generated decoder
// surfaces a 421 jurisdiction redirect.
func jurisdictionErr(fields map[string]string) *ErrorModelStatusCode {
	props := ErrorModelAdditional{}
	for k, v := range fields {
		props[k] = jx.Raw(fmt.Sprintf("%q", v))
	}
	return &ErrorModelStatusCode{StatusCode: 421, Response: ErrorModel{AdditionalProps: props}}
}

func TestRegionalRedirectFrom(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		err      error
		wantOK   bool
		wantHome string
		wantJuri string
		wantMsg  string
	}{
