// mirrorRedirectError renders a 421 cross-jurisdiction redirect. It
// implements huma.StatusError, so huma marshals this value (not its default
// ErrorModel) as the response body.
//
// The body converges on the documented corev1.MeRegionalUnavailable shape —
// error discriminator + camelCase homeCoreUrl + message — while still emitting
// the legacy snake_case home_core_url alias. Two clients read the URL:
// the `entire` CLI (now tolerant of both spellings) and entiredb's own
// crossJurisRoundTripper (internal/cliauth/cross_juris_transport.go), which
// still reads home_core_url only. Drop HomeCoreURLLegacy once that transport
// reads homeCoreUrl and no pre-dual-emit clients remain in the wild.
type mirrorRedirectError struct {
	status int
	// ErrorCode is the discriminator clients pattern-match on; always
	// "foreign_jurisdiction", matching corev1.MeRegionalUnavailable.
	ErrorCode string `json:"error"`
	// Message is the human-readable explanation.
	Message string `json:"message"`
	// HomeCoreURL is the documented camelCase field; HomeCoreURLLegacy is the
	// snake_case alias kept for older clients.
	HomeCoreURL       string `json:"homeCoreUrl"`
	HomeCoreURLLegacy string `json:"home_core_url"`
	Jurisdiction      string `json:"jurisdiction,omitempty"`
}

func (e *mirrorRedirectError) Error() string  { return e.Message }

