package coreapi

import (
	"encoding/json"
	"net/http"
	"testing"
)

// TestMirrorRedirectError_WireShape pins the 421 cross-jurisdiction body. It
// emits the documented corev1.MeRegionalUnavailable shape (error discriminator
// + camelCase homeCoreUrl + message) AND the legacy snake_case home_core_url
// alias that entiredb's crossJurisRoundTripper still reads. If the alias is
// dropped before that transport is updated, the entiredb CLI's 421 auto-retry
// breaks — so this guards both spellings until then.
func TestMirrorRedirectError_WireShape(t *testing.T) {
	t.Parallel()
	e := &mirrorRedirectError{
		status:            http.StatusMisdirectedRequest,
		ErrorCode:         "foreign_jurisdiction",
		Message:           `cluster is in jurisdiction "us"; retry against the home core`,
		HomeCoreURL:       "https://us.auth.partial.to",
		HomeCoreURLLegacy: "https://us.auth.partial.to",
		Jurisdiction:      "us",
	}

	raw, err := json.Marshal(e)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var body map[string]any
	if err := json.Unmarshal(raw, &body); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}

	want := map[string]string{
		"error":         "foreign_jurisdiction",                                      // discriminator (documented)
		"message":       `cluster is in jurisdiction "us"; retry against the home core`, // human text (documented)
		"homeCoreUrl":   "https://us.auth.partial.to",                                // documented camelCase
		"home_core_url": "https://us.auth.partial.to",                                // legacy alias (entiredb transport)
		"jurisdiction":  "us",
	}
	for k, v := range want {
		if got, _ := body[k].(string); got != v {
			t.Errorf("body[%q] = %q, want %q", k, got, v)
		}
	}

	if e.GetStatus() != http.StatusMisdirectedRequest {
		t.Errorf("GetStatus() = %d, want 421", e.GetStatus())
	}
	if ct := e.ContentType("application/json"); ct != "application/problem+json" {
		t.Errorf("ContentType = %q, want application/problem+json", ct)
	}
}

