1	package coreapi
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"net/http"
9		"strings"
10	
11		"github.com/danielgtaylor/huma/v2"
12	
13		"entire.io/api/corev1"
14		"entire.io/core/api"
15		"entire.io/core/model"
16		"entire.io/slogutil"
17	)
18	
19	// MirrorService backs /api/v1/mirrors. The handlers are thin huma
20	// adapters: List/Get read via api.Server accessors, while Create/Delete
21	// orchestrate through api.Server.CreateMirrorPlacement /
22	// DeleteMirrorPlacement (the cross-jurisdiction redirect, GitHub-perms,
23	// and NATS-publish flows live there, where their dependencies are wired).
24	type MirrorService struct {
25		Server *api.Server
26	}
27	
28	// ListMirrors returns the mirrors the calling account owns or can push
29	// to. Mirror authz is GitHub-based, not SpiceDB, so the visible set comes
30	// from WritableMirrorRows (write+ on the upstream), not a repo#pull
31	// reverse lookup — listing every public mirror in the jurisdiction would
32	// be noise. Filters (cluster, provider, owner) are applied client-side
33	// after the visibility scan so a missing provider filter still scopes to
34	// GitHub.
35	func (s *MirrorService) ListMirrors(ctx context.Context, in *corev1.ListMirrorsInput) (*corev1.ListMirrorsOutput, error) {
36		claims := api.ClaimsFromContext(ctx)
37		if claims == nil {
38			return nil, unauthorized("authentication required")
39		}
40		rows, err := s.Server.WritableMirrorRows(ctx, claims.AccountID)
41		if err != nil {
42			slogutil.Error(ctx, "WritableMirrorRows failed", slog.Any("error", err))
43			return nil, internalErr()
44		}
45		// mirrorrepo.ListAll currently returns only GitHub-backed mirrors —
46		// see core/mirrorrepo's ProviderGitHub comment. Surface each row's
47		// provider via a single source of truth so the filter compares
48		// row.Provider == in.Provider rather than hard-coding the only
49		// supported provider into the filter logic, where it would silently
50		// misbehave the day a second provider is added.
51		const rowProvider = "github"
52		// Resolve each row's cluster slug to its public host once per slug —
53		// mirror lists span few clusters, so the memo keeps this O(clusters)
54		// rather than O(rows).
55		hostFor := s.clusterHostMemo(ctx)
56		out := &corev1.ListMirrorsOutput{}
57		out.Body.Mirrors = make([]corev1.Mirror, 0, len(rows))
58		for _, r := range rows {
59			host := hostFor(r.ClusterSlug)
60			if in.Cluster != "" && host != in.Cluster {
61				continue
62			}
63			if in.Provider != "" && !strings.EqualFold(in.Provider, rowProvider) {
64				continue
65			}
66			if in.Owner != "" && !strings.EqualFold(r.OwnerLogin, in.Owner) {
67				continue
68			}
69			m := corev1.Mirror{
70				MirrorID:     r.ID.String(),
71				Provider:     "github",
72				Owner:        r.OwnerLogin,
73				Repo:         r.RepoName,
74				ClusterHost:  host,
75				Jurisdiction: r.Jurisdiction,
76				IsPrivate:    r.IsPrivate,
77				IsArchived:   r.IsArchived,
78				CreatedAt:    r.CreatedAt,
79				SuspendedAt:  r.SuspendedAt,
80			}
81			if r.InstallationID != nil {
82				m.InstallationID = *r.InstallationID
83			}
84			out.Body.Mirrors = append(out.Body.Mirrors, m)
85		}
86		return out, nil
87	}
88	
89	// clusterHostMemo returns a slug→public-host resolver that caches results
90	// for the lifetime of one request, so a mirror list spanning many rows but
91	// few clusters does at most one lookup per distinct slug. Resolution failures
92	// (unwired store, unknown slug) memoize as "".
93	func (s *MirrorService) clusterHostMemo(ctx context.Context) func(slug string) string {
94		return clusterHostMemo(ctx, s.Server)
95	}
96	
97	// entireRemote assembles the full entire:// remote a client can clone
98	// from its two locating primitives. Errors when either is missing rather
99	// than emitting a scheme with an empty authority or a host with no path —
100	// a half-formed remote is worse than a loud failure the caller can report.
101	func entireRemote(host, path string) (string, error) {
102		if host == "" {
103			return "", errors.New("unresolved cluster public host")
104		}
105		if path == "" {
106			return "", errors.New("empty repo path")
107		}
108		return "entire://" + host + path, nil
109	}
110	
111	// clusterHostMemo is the package-level helper backing both
112	// MirrorService.clusterHostMemo and the lookup-enrichment path in
113	// IdentityService — same memoization, same fail-quiet shape.
114	func clusterHostMemo(ctx context.Context, srv *api.Server) func(slug string) string {
115		cache := make(map[string]string)
116		return func(slug string) string {
117			if h, ok := cache[slug]; ok {
118				return h
119			}
120			h, err := srv.ClusterPublicHost(ctx, slug)
121			if err != nil {
122				slogutil.Error(ctx, "ClusterPublicHost failed", slog.String("slug", slug), slog.Any("error", err))
123				h = ""
124			}
125			cache[slug] = h
126			return h
127		}
128	}
129	
130	// GetMirror returns one mirror by ID. 404 when the caller doesn't own or
131	// can't push to the underlying repo, matching the listing's visibility
132	// rule and keeping the endpoint enumeration-safe.
133	func (s *MirrorService) GetMirror(ctx context.Context, in *corev1.GetMirrorInput) (*corev1.GetMirrorOutput, error) {
134		claims := api.ClaimsFromContext(ctx)
135		if claims == nil {
136			return nil, unauthorized("authentication required")
137		}
138		mirrorID, err := model.ParseRepoID(in.MirrorID)
139		if err != nil {
140			return nil, badRequest("invalid mirror id")
141		}
142		// Mirror visibility is a GitHub-perms decision, not a SpiceDB tuple:
143		// membership in the caller's writable-mirror set (write+ on the
144		// upstream). A mirror the caller doesn't own is absent from the rows
145		// and falls through to 404 (not 403) so the endpoint isn't an
146		// enumeration oracle.
147		rows, err := s.Server.WritableMirrorRows(ctx, claims.AccountID)
148		if err != nil {
